mapper.select:
select bm_weigh_ticket_requirement.storage_material_batch_id, ifnull(bm_weigh_ticket_requirement.formula_quantity, 0) as occupancy_quantity, bm_weigh_ticket_requirement.unit_id from bm_weigh_ticket_requirement left join bm_weigh_ticket_requirement_group on bm_weigh_ticket_requirement.requirement_group_id = bm_weigh_ticket_requirement_group.id and bm_weigh_ticket_requirement.is_deleted = 0 where bm_weigh_ticket_requirement.is_deleted = 0 and bm_weigh_ticket_requirement.requirement_status in (0, 1, 2) and bm_weigh_ticket_requirement_group.release_status in (0, 1)
and bm_weigh_ticket_requirement.storage_material_batch_id in
#{item}
and bm_weigh_ticket_requirement.requirement_key != #{expectKey}

select bm_weigh_ticket_requirement.id, bm_material.name as material_name, bm_material.merge_code as material_merge_code, bm_material.specification as material_specification, bm_storage_material_batch.material_batch_no as storage_material_batch_no, bm_storage_material_batch.id as storage_material_batch_id, bm_weigh_centre.name as weigh_centre_name, bm_weigh_ticket_requirement.formula_quantity as formula_quantity, product.name as product_name, product.merge_code as product_merge_code, bm_weigh_ticket_requirement_group.batch_no as batch_no, bm_weigh_ticket_requirement.plan_date as plan_date, bm_weigh_ticket_requirement.requirement_usage as requirement_usage, bm_weigh_ticket_requirement_group.remark, bm_weigh_ticket_requirement.unit_id from bm_weigh_ticket_requirement left join bm_material on bm_weigh_ticket_requirement.material_id = bm_material.id and bm_material.is_deleted = 0 left join bm_storage_material_batch on bm_weigh_ticket_requirement.storage_material_batch_id = bm_storage_material_batch.id and bm_storage_material_batch.is_deleted = 0 left join bm_weigh_centre on bm_weigh_ticket_requirement.weigh_centre_id = bm_weigh_centre.id and bm_weigh_centre.is_deleted = 0 left join bm_product_formula_material on bm_weigh_ticket_requirement.formula_material_id = bm_product_formula_material.id and bm_product_formula_material.is_deleted = 0 left join bm_weigh_ticket_requirement_group on bm_weigh_ticket_requirement.requirement_group_id = bm_weigh_ticket_requirement_group.id and bm_weigh_ticket_requirement_group.is_deleted = 0 left join bm_material product on bm_weigh_ticket_requirement_group.material_id = product.id and product.is_deleted = 0 where (bm_weigh_ticket_requirement.is_deleted = 0 and bm_weigh_ticket_requirement_group.release_status = 1
AND bm_material.name LIKE CONCAT('%', #{query.materialName}, '%')
AND bm_material.merge_code = #{query.materialMergeCode}
AND bm_storage_material_batch.material_batch_no like CONCAT('%', #{query.storageMaterialBatchNo}, '%')
AND bm_weigh_centre.name LIKE CONCAT('%', #{query.weighCentreName}, '%')
AND bm_product_formula_material.material_name LIKE CONCAT('%', #{query.productName}, '%')
AND product.id = #{query.productId}
AND bm_weigh_ticket_requirement_group.batch_no like CONCAT('%', #{query.batchNo}, '%')
AND bm_weigh_ticket_requirement.plan_date >= #{query.planDateStart}
AND bm_weigh_ticket_requirement.plan_date <= #{query.planDateEnd}
AND bm_weigh_ticket_requirement.material_id = #{query.materialId}
AND bm_weigh_ticket_requirement.storage_material_batch_id = #{query.storageMaterialBatchId}
AND bm_weigh_ticket_requirement.unit_id = #{query.unitId}
AND bm_weigh_ticket_requirement.weigh_centre_id = #{query.weighCentreId}
and bm_weigh_ticket_requirement.requirement_status = 0
AND bm_weigh_ticket_requirement.ticket_id = #{query.ticketId} and bm_weigh_ticket_requirement.requirement_status != 0
and bm_weigh_ticket_requirement.id not in
#{item}
)
or bm_weigh_ticket_requirement.id in
#{item}
and bm_weigh_ticket_requirement.weigh_centre_id in
#{item}
order by bm_weigh_ticket_requirement.plan_date
